using namespace std;

bool reachable(const string& S, const string& T) {
    int n = S.size(), m = T.size();
    if (m > n) return false;
    // dp[i][j] = true if T[0..j-1] matched using S ending at position i (1-indexed)
    // with valid jumps
    vector<vector<bool>> dp(n+1, vector<bool>(m+1, false));
    dp[0][0] = true;
    for (int i = 1; i <= n; i++) {
        dp[i][0] = false; // can't match 0 chars of T ending at i (unless m=0)
    }
    dp[0][0] = true;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (S[i-1] == T[j-1]) {
                if (j == 1) {
                    dp[i][j] = (i <= 2); // first char must be at position 1 or 2
                } else {
                    dp[i][j] = (i >= 2 && dp[i-1][j-1]) || (i >= 3 && dp[i-2][j-1]);
                }
            }
        }
    }
    return dp[n][m];
}

