        for (int i = 0; i < n; i++) {
            for (int j = i+1; j < n; j++) {
                if (canObtain(s[i], s[j]) || canObtain(s[j], s[i])) ans++;
            }
        }
        System.out.println(ans);
    }

    // Can we obtain T from S?
    static boolean canObtain(String S, String T) {
        // Find longest common prefix
        int m = 0;
        while (m < S.length() && m < T.length() && S.charAt(m) == T.charAt(m)) m++;
        // T[m:] must be a suffix of S[m:]
        String Tsuf = T.substring(m);
        String Ssuf = S.substring(m);
        return Ssuf.endsWith(Tsuf);
    }
}

