int can_transform(char *a, char *b) {
    // returns 1 if b can be obtained from a
    int len_a = strlen(a);
    int len_b = strlen(b);
    if (len_a < len_b) return 0;
    int i = 0, j = 0;
    while (i < len_a && j < len_b) {
        if (a[i] == b[j]) {
            i++;
            j++;
        } else {
            i++;
        }
        // We can skip at most one character ahead before matching
        // Actually we must ensure we don't skip 2 in a row at the start - 
        // but this greedy works because we can always delete first or second.
        // The rule: if we skip, we skip exactly one and then must match next or skip again.
    }
    return j == len_b;
}

