int is_subsequence(const char *s, const char *t) {
    // Is t a subsequence of s?
    int i = 0, j = 0;
    int ls = strlen(s), lt = strlen(t);
    while (i < ls && j < lt) {
        if (s[i] == t[j]) j++;
        i++;
    }
    return j == lt;
}

