typedef unsigned long long U64;

typedef struct {
    U64 h1, h2;
    int len;
} Key;

typedef struct {
    Key key;
    long long cnt;
    int used;
} HashEntry;

static const U64 BASE1 = 911382323ULL;
static const U64 BASE2 = 972663749ULL;

static int key_equal(Key a, Key b) {
    return a.h1 == b.h1 && a.h2 == b.h2 && a.len == b.len;
}

static U64 mix64(U64 x) {
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

static U64 key_hash(Key k) {
    U64 x = k.h1 ^ (k.h2 + 0x9e3779b97f4a7c15ULL + (k.h1 << 6) + (k.h1 >> 2));
    x ^= (U64)k.len * 11995408973635179863ULL;
    return mix64(x);
}

static void map_add(HashEntry *tab, int size, Key key, long long delta) {
    U64 h = key_hash(key);
    int idx = (int)(h & (size - 1));
    while (tab[idx].used) {
        if (key_equal(tab[idx].key, key)) {
            tab[idx].cnt += delta;
            return;
        }
        idx = (idx + 1) & (size - 1);
    }
    tab[idx].used = 1;
    tab[idx].key = key;
    tab[idx].cnt = delta;
}

static long long map_get(HashEntry *tab, int size, Key key) {
    U64 h = key_hash(key);
    int idx = (int)(h & (size - 1));
    while (tab[idx].used) {
        if (key_equal(tab[idx].key, key)) return tab[idx].cnt;
        idx = (idx + 1) & (size - 1);
    }
    return 0;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    char **strs = (char **)malloc((size_t)N * sizeof(char *));
    int *lens = (int *)malloc((size_t)N * sizeof(int));

    long long total_states = 0;
    char buffer[1000005];

    for (int i = 0; i < N; i++) {
        scanf("%s", buffer);
        int len = (int)strlen(buffer);
        strs[i] = (char *)malloc((size_t)len + 1);
        memcpy(strs[i], buffer, (size_t)len + 1);
        lens[i] = len;
        total_states += (long long)len + 1;
    }

    int size = 1;
    while (size < 4 * total_states) size <<= 1;
    HashEntry *freq = (HashEntry *)calloc((size_t)size, sizeof(HashEntry));

    for (int i = 0; i < N; i++) {
        char *s = strs[i];
        int L = lens[i];

        U64 *pow1 = (U64 *)malloc((size_t)(L + 1) * sizeof(U64));
        U64 *pow2 = (U64 *)malloc((size_t)(L + 1) * sizeof(U64));
        U64 *pref1 = (U64 *)malloc((size_t)(L + 1) * sizeof(U64));
        U64 *pref2 = (U64 *)malloc((size_t)(L + 1) * sizeof(U64));

        pow1[0] = pow2[0] = 1;
        pref1[0] = pref2[0] = 0;
        for (int j = 0; j < L; j++) {
            unsigned char c = (unsigned char)s[j] + 1;
            pow1[j + 1] = pow1[j] * BASE1;
            pow2[j + 1] = pow2[j] * BASE2;
            pref1[j + 1] = pref1[j] * BASE1 + c;
            pref2[j + 1] = pref2[j] * BASE2 + c;
        }

        for (int k = 0; k <= L; k++) {
            Key key;
            if (k == 0) {
                key.h1 = pref1[L];
                key.h2 = pref2[L];
                key.len = L;
                map_add(freq, size, key, 1);
            } else if (k == 1) {
                key.h1 = pref1[L] - pref1[1] * pow1[L - 1];
                key.h2 = pref2[L] - pref2[1] * pow2[L - 1];
                key.len = L - 1;
                map_add(freq, size, key, 1);
            } else {
                int rem = k - 2;
                int suf_len = L - k;
                U64 suf1 = pref1[L] - pref1[k] * pow1[suf_len];
                U64 suf2 = pref2[L] - pref2[k] * pow2[suf_len];
                unsigned char c = (unsigned char)s[1 + rem] + 1;
                key.h1 = ((U64)c) * pow1[suf_len] + suf1;
                key.h2 = ((U64)c) * pow2[suf_len] + suf2;
                key.len = L - 1 - rem;
                map_add(freq, size, key, 1);
            }
        }

        free(pow1);
        free(pow2);
        free(pref1);
        free(pref2);
    }

    long long ans = 0;

    for (int i = 0; i < N; i++) {
        int L = lens[i];
        char *s = strs[i];

        U64 h1 = 0, h2 = 0;
        for (int j = 0; j < L; j++) {
            unsigned char c = (unsigned char)s[j] + 1;
            h1 = h1 * BASE1 + c;
            h2 = h2 * BASE2 + c;
        }
        Key key = {h1, h2, L};
        ans += map_get(freq, size, key) - 1; /* exclude itself */

        free(strs[i]);
    }

    free(strs);
    free(lens);
    free(freq);

    printf("%lld\n", ans / 2);
    return 0;
}

import sys

def solve() -> None:
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    strings = input_data[1:]

    # Group strings by length
    by_length = {}
    for s in strings:
        l = len(s)
        by_length.setdefault(l, []).append(s)

    lengths = sorted(by_length.keys())
    count = 0

    # Track all suffixes seen so far (from longer strings)
    seen_suffixes = set()

    # Process from longest to shortest
    for l in reversed(lengths):
        for s in by_length[l]:
            # Check if this string is a suffix of any already seen longer string
            if s in seen_suffixes:
                count += 1
        # After checking, add all suffixes of current strings
        for s in by_length[l]:
            for start in range(len(s)):
                seen_suffixes.add(s[start:])

    print(count)

