import sys
from functools import lru_cache

def is_reachable(S, T):
    # Is T reachable from S?
    n, m = len(S), len(T)
    if m > n:
        return False
    # dp[i][j] = can we match T[j:] using S[i:] with the constraint
    # We need to pick indices from S, last must be n-1, consecutive diff <= 2
    # dp[i][j]: True if T[j:] can be matched from S starting at position i
    # with next pick being i or i+1
    if m == n:
        return S == T
    # Use DP
    dp = [[False]*(m+1) for _ in range(n+1)]
    for i in range(n+1):
        dp[i][m] = True  # matched all of T
    for j in range(m-1, -1, -1):
        for i in range(n-1, -1, -1):
            if S[i] == T[j]:
                # pick i, next must be in [i+1, i+2]
                if i == n-1 and j == m-1:
                    dp[i][j] = True
                elif i+1 <= n-1:
                    dp[i][j] = dp[i+1][j+1] or (i+2 <= n-1 and dp[i+2][j+1])
    return any(dp[i][0] for i in range(min(2, n)))

